const CSS = ":root {\n  --bg: #05070d;\n  --bg-elev: #0b101c;\n  --panel: #0f1626;\n  --panel-hi: #141e33;\n  --line: rgba(148, 163, 184, 0.16);\n  --line-hi: rgba(45, 212, 191, 0.45);\n  --fg: #f1f5f9;\n  --muted: #94a3b8;\n  --dim: #64748b;\n  --cyan: #2dd4bf;\n  --sky: #38bdf8;\n  --indigo: #818cf8;\n  --ok: #34d399;\n  --warn: #fbbf24;\n  --rose: #fb7185;\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--fg);\n  font: 15.5px/1.6 \"Inter\", \"Segoe UI\", system-ui, -apple-system, sans-serif;\n  overflow-x: hidden;\n}\na { color: var(--sky); text-decoration: none; transition: color 0.15s ease; }\na:hover { color: var(--cyan); }\n\n/* Ambient Aurora Background */\n.aurora-bg {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  z-index: 0;\n  background:\n    radial-gradient(900px 420px at 15% -5%, rgba(45, 212, 191, 0.12), transparent 65%),\n    radial-gradient(850px 460px at 88% 8%, rgba(56, 189, 248, 0.12), transparent 65%),\n    radial-gradient(700px 400px at 50% 95%, rgba(129, 140, 248, 0.08), transparent 65%);\n}\n\n/* Top Announcement Bar */\n.announce-bar {\n  position: relative;\n  z-index: 20;\n  background: linear-gradient(90deg, rgba(15, 22, 38, 0.95), rgba(20, 30, 51, 0.95));\n  border-bottom: 1px solid var(--line);\n  padding: 8px 20px;\n  text-align: center;\n  font-size: 12.5px;\n  color: var(--muted);\n  letter-spacing: 0.03em;\n}\n.announce-bar b { color: var(--cyan); font-weight: 600; }\n.announce-bar a { color: var(--fg); text-decoration: underline; text-underline-offset: 3px; margin-left: 8px; font-weight: 600; }\n\n/* Sticky Glassmorphic Header */\n.site-nav {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  background: rgba(5, 7, 13, 0.82);\n  border-bottom: 1px solid var(--line);\n}\n.site-nav-inner {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 14px 24px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n.brand-logo {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  font-weight: 800;\n  font-size: 18px;\n  color: var(--fg);\n  letter-spacing: -0.02em;\n}\n.brand-logo .dot {\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n  background: var(--cyan);\n  box-shadow: 0 0 12px var(--cyan);\n}\n.brand-logo span { color: var(--cyan); font-weight: 600; font-size: 13px; padding: 2px 8px; border-radius: 999px; background: rgba(45, 212, 191, 0.12); border: 1px solid rgba(45, 212, 191, 0.3); }\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 18px;\n  flex-wrap: wrap;\n  font-size: 13.5px;\n}\n.nav-links a { color: var(--muted); font-weight: 500; }\n.nav-links a:hover { color: var(--fg); }\n.nav-links a.cta-pill {\n  color: #041019;\n  background: linear-gradient(135deg, var(--cyan), var(--sky));\n  padding: 7px 15px;\n  border-radius: 999px;\n  font-weight: 700;\n}\n\n.wrap {\n  position: relative;\n  z-index: 2;\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 40px 24px 80px;\n}\n\n/* Scrolltide Hero */\n.hero-sec {\n  text-align: center;\n  padding: 28px 0 36px;\n  max-width: 940px;\n  margin: 0 auto;\n}\n.eyebrow-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 16px;\n  border-radius: 999px;\n  background: rgba(45, 212, 191, 0.1);\n  border: 1px solid rgba(45, 212, 191, 0.32);\n  color: var(--cyan);\n  font-size: 12.5px;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  margin-bottom: 18px;\n}\nh1 {\n  font-size: clamp(2.2rem, 4.8vw, 3.8rem);\n  line-height: 1.08;\n  letter-spacing: -0.03em;\n  margin: 0 0 18px;\n  font-weight: 800;\n}\nh1 .grad {\n  background: linear-gradient(95deg, #2dd4bf 0%, #38bdf8 52%, #818cf8 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n.lede {\n  color: var(--muted);\n  font-size: clamp(1rem, 1.8vw, 1.18rem);\n  max-width: 760px;\n  margin: 0 auto 26px;\n}\n.hero-actions {\n  display: flex;\n  justify-content: center;\n  gap: 12px;\n  flex-wrap: wrap;\n  margin-bottom: 28px;\n}\n.btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 11px 20px;\n  border-radius: 10px;\n  border: 1px solid var(--line);\n  background: var(--panel);\n  color: var(--fg);\n  font-weight: 600;\n  font-size: 14px;\n  cursor: pointer;\n  transition: all 0.18s ease;\n}\n.btn:hover {\n  border-color: var(--cyan);\n  transform: translateY(-1px);\n  color: var(--fg);\n}\n.btn.primary {\n  background: linear-gradient(135deg, var(--cyan), var(--sky));\n  color: #041019;\n  border-color: transparent;\n  font-weight: 700;\n}\n.btn.primary:hover {\n  filter: brightness(1.08);\n  color: #041019;\n}\n\n/* Proof Stat Strip */\n.proof-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 12px;\n  margin: 24px 0 42px;\n}\n.proof-box {\n  background: rgba(15, 22, 38, 0.78);\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 14px 16px;\n  text-align: left;\n}\n.proof-box b {\n  display: block;\n  font-size: 20px;\n  color: var(--cyan);\n  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n}\n.proof-box span {\n  font-size: 12.5px;\n  color: var(--muted);\n}\n\n/* NotebookLM Video Overview Studio Section */\n.nlm-section {\n  background: linear-gradient(180deg, rgba(15, 22, 38, 0.92), rgba(11, 16, 28, 0.96));\n  border: 1px solid rgba(45, 212, 191, 0.35);\n  border-radius: 20px;\n  padding: 28px;\n  margin-bottom: 48px;\n  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);\n}\n.nlm-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 16px;\n  flex-wrap: wrap;\n  margin-bottom: 20px;\n}\n.nlm-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 5px 12px;\n  border-radius: 999px;\n  background: rgba(45, 212, 191, 0.14);\n  border: 1px solid rgba(45, 212, 191, 0.4);\n  color: var(--cyan);\n  font-size: 12px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n.nlm-grid {\n  display: grid;\n  grid-template-columns: 1.55fr 1fr;\n  gap: 22px;\n  align-items: stretch;\n}\n.video-frame {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  background: #070a11;\n  border-radius: 14px;\n  overflow: hidden;\n  border: 1px solid var(--line);\n}\n.video-frame video, .video-frame img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  display: block;\n  background: #070a11;\n}\n.nlm-chapters {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  justify-content: space-between;\n}\n.nlm-chap {\n  background: rgba(9, 13, 22, 0.85);\n  border: 1px solid var(--line);\n  border-radius: 12px;\n  padding: 12px 14px;\n  cursor: pointer;\n  text-align: left;\n  color: var(--fg);\n  transition: border-color 0.15s, background 0.15s;\n}\n.nlm-chap:hover {\n  border-color: var(--cyan);\n  background: rgba(20, 30, 51, 0.9);\n}\n.nlm-chap .ch-top {\n  display: flex;\n  justify-content: space-between;\n  font-size: 11.5px;\n  font-family: ui-monospace, Consolas, monospace;\n  color: var(--cyan);\n  margin-bottom: 4px;\n}\n.nlm-chap b { display: block; font-size: 14px; margin-bottom: 2px; }\n.nlm-chap span { font-size: 12.5px; color: var(--muted); }\n\n/* Filter Bar */\n.filter-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  flex-wrap: wrap;\n  margin: 36px 0 22px;\n  padding-bottom: 16px;\n  border-bottom: 1px solid var(--line);\n}\n.filter-tabs {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.ftab {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  color: var(--muted);\n  padding: 7px 14px;\n  border-radius: 999px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n.ftab:hover, .ftab.active {\n  background: var(--cyan);\n  color: #041019;\n  border-color: var(--cyan);\n}\n.search-box {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  color: var(--fg);\n  padding: 8px 14px;\n  border-radius: 10px;\n  font-size: 13.5px;\n  min-width: 240px;\n}\n\n/* Scrolltide Showcase Cards (.grid and .card required by verify.py) */\n.grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(370px, 1fr));\n  gap: 22px;\n}\n.card {\n  display: flex;\n  flex-direction: column;\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 16px;\n  overflow: hidden;\n  color: var(--fg);\n  text-decoration: none;\n  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;\n}\n.card:hover {\n  border-color: var(--line-hi);\n  transform: translateY(-3px);\n  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.55);\n  color: var(--fg);\n}\n.card-media {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  background: #070a11;\n  border-bottom: 1px solid var(--line);\n  overflow: hidden;\n}\n.card-media video, .card-media img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  display: block;\n  background: #070a11;\n}\n.card-badge {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  background: rgba(5, 7, 13, 0.86);\n  border: 1px solid rgba(45, 212, 191, 0.4);\n  color: var(--cyan);\n  font-size: 11px;\n  font-weight: 700;\n  padding: 3px 9px;\n  border-radius: 999px;\n  backdrop-filter: blur(8px);\n}\n.card-play-hint {\n  position: absolute;\n  bottom: 10px;\n  right: 10px;\n  background: rgba(5, 7, 13, 0.85);\n  border: 1px solid var(--line);\n  color: var(--fg);\n  font-size: 11px;\n  font-family: ui-monospace, Consolas, monospace;\n  padding: 3px 8px;\n  border-radius: 6px;\n}\n.card-body {\n  padding: 18px 20px 20px;\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n}\n.card h2 {\n  font-size: 1.18rem;\n  margin: 0 0 6px;\n  color: var(--fg);\n}\n.card p {\n  margin: 0 0 14px;\n  color: var(--muted);\n  font-size: 0.92rem;\n}\n\n/* Concrete Input -> Output Box inside every card */\n.io-box {\n  background: rgba(7, 10, 17, 0.85);\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 10px 12px;\n  margin-bottom: 12px;\n  font-size: 12.5px;\n}\n.io-row {\n  display: flex;\n  gap: 8px;\n  margin: 4px 0;\n  align-items: baseline;\n}\n.io-tag {\n  font-family: ui-monospace, Consolas, monospace;\n  font-size: 10.5px;\n  font-weight: 700;\n  padding: 1px 6px;\n  border-radius: 4px;\n  flex-shrink: 0;\n}\n.io-tag.in { background: rgba(251, 113, 133, 0.16); color: #fda4af; border: 1px solid rgba(251, 113, 133, 0.35); }\n.io-tag.out { background: rgba(52, 211, 153, 0.16); color: #6ee7b7; border: 1px solid rgba(52, 211, 153, 0.35); }\n.io-text { color: #cbd5e1; line-height: 1.4; }\n.io-code {\n  margin-top: 6px;\n  padding-top: 6px;\n  border-top: 1px dashed rgba(148, 163, 184, 0.18);\n  font-family: ui-monospace, Consolas, monospace;\n  font-size: 11px;\n  color: var(--cyan);\n  overflow-x: auto;\n  white-space: nowrap;\n}\n\n.card .caveat {\n  margin-top: auto;\n  padding-top: 10px;\n  border-top: 1px solid var(--line);\n  color: var(--dim);\n  font-size: 0.8rem;\n}\n.card-foot {\n  margin-top: 12px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--cyan);\n}\n\n/* Detail Page Styles (/apps/<slug>/) */\n.detail-grid {\n  display: grid;\n  grid-template-columns: 1.45fr 1fr;\n  gap: 26px;\n  margin: 24px 0 32px;\n}\n.panel-box {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 16px;\n  padding: 22px;\n  margin-bottom: 20px;\n}\n.panel-box h2 {\n  margin: 0 0 12px;\n  font-size: 1.15rem;\n  color: var(--fg);\n}\n.step-cards {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 16px;\n  margin: 20px 0;\n}\n.step-card {\n  background: rgba(9, 13, 22, 0.9);\n  border: 1px solid var(--line);\n  border-radius: 14px;\n  padding: 16px;\n}\n.step-card h3 {\n  margin: 0 0 8px;\n  font-size: 13px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--cyan);\n  font-family: ui-monospace, Consolas, monospace;\n}\n.caveat-box {\n  border-left: 3px solid var(--warn);\n  padding: 14px 18px;\n  background: rgba(251, 191, 36, 0.07);\n  border-radius: 0 12px 12px 0;\n  margin: 20px 0;\n}\n.links { display: flex; gap: 12px; flex-wrap: wrap; margin: 20px 0; }\n.links a {\n  padding: 10px 16px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: var(--panel);\n  color: var(--fg);\n  font-weight: 600;\n}\n.links a.primary {\n  background: linear-gradient(135deg, var(--cyan), var(--sky));\n  color: #041019;\n  border-color: transparent;\n  font-weight: 700;\n}\nfooter {\n  margin-top: 56px;\n  padding-top: 24px;\n  border-top: 1px solid var(--line);\n  color: var(--muted);\n  font-size: 0.88rem;\n  display: flex;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n}\n@media (max-width: 920px) {\n  .nlm-grid, .detail-grid, .step-cards { grid-template-columns: 1fr; }\n  .grid { grid-template-columns: 1fr; }\n}\n";
const SW_KILL = "self.addEventListener('install',function(e){self.skipWaiting()});self.addEventListener('activate',function(e){e.waitUntil((async function(){try{var k=await caches.keys();await Promise.all(k.map(function(x){return caches.delete(x)}))}catch(e){}try{await self.registration.unregister()}catch(e){}try{var cs=await self.clients.matchAll({includeUncontrolled:true});for(var i=0;i<cs.length;i++){try{cs[i].navigate(cs[i].url)}catch(e){}}}catch(e){}})())});";
